-- Uvoz odprodaje/zaloge odprodaje v pim.ClearanceItem.
-- Vir podatkov: 5 Excel datotek iz C:\Users\David\Downloads\Odprodaja (260 vrstic).
-- Stran (NaSvetila/NaVidelektro) je iz zivega izvoza katalog.csv, stanje na 8. 09. 2026 06:00:19.
-- Predpogoj: migracija 153_ClearanceItem.sql je ze pognana (pim.ClearanceItem obstaja).
-- Skripta je varna za ponovni zagon (MERGE po Sifra+Vir, ne podvaja vrstic).

USE PIM;
SET NOCOUNT ON;

IF OBJECT_ID(N'pim.ClearanceItem', N'U') IS NULL
  THROW 51000, N'pim.ClearanceItem ne obstaja - najprej pozeni migracijo 153_ClearanceItem.sql.', 1;

IF OBJECT_ID('tempdb..#Odprodaja') IS NOT NULL DROP TABLE #Odprodaja;
CREATE TABLE #Odprodaja
(
  Vir nvarchar(100) COLLATE DATABASE_DEFAULT NOT NULL,
  Sifra nvarchar(100) COLLATE DATABASE_DEFAULT NOT NULL,
  Ean nvarchar(100) COLLATE DATABASE_DEFAULT NULL,
  NaSvetila bit NOT NULL,
  NaVidelektro bit NOT NULL,
  Kolicina decimal(19,4) NULL,
  RednaCena decimal(19,4) NULL,
  PopustOdstotek decimal(5,2) NULL,
  OdprodajnaCena decimal(19,4) NULL,
  IzvornaDatoteka nvarchar(260) COLLATE DATABASE_DEFAULT NULL
);


-- Za vsako (Sifra) izberi en ProductId: prednost IQLighting(2), potem Vidadria(3), DEMO(1), Ediito(4).
;WITH Kandidati AS (
  SELECT o.*, p.ProductId,
         ROW_NUMBER() OVER (
           PARTITION BY o.Sifra, o.Vir
           ORDER BY CASE p.OrganizationId WHEN 2 THEN 0 WHEN 3 THEN 1 WHEN 1 THEN 2 WHEN 4 THEN 3 ELSE 9 END
         ) AS rn
  FROM #Odprodaja o
  JOIN canon.Product p ON UPPER(LTRIM(RTRIM(p.ItemID))) COLLATE SQL_Latin1_General_CP1_CI_AS
                        = UPPER(LTRIM(RTRIM(o.Sifra))) COLLATE SQL_Latin1_General_CP1_CI_AS
),
Izbrano AS (
  SELECT * FROM Kandidati WHERE rn = 1
)
MERGE pim.ClearanceItem AS target
USING Izbrano AS src
  ON target.ProductId = src.ProductId
 AND target.Vir COLLATE SQL_Latin1_General_CP1_CI_AS = src.Vir COLLATE SQL_Latin1_General_CP1_CI_AS
WHEN MATCHED THEN
  UPDATE SET Sifra = src.Sifra, Ean = src.Ean, NaSvetila = src.NaSvetila, NaVidelektro = src.NaVidelektro,
             Kolicina = src.Kolicina, RednaCena = src.RednaCena, PopustOdstotek = src.PopustOdstotek,
             OdprodajnaCena = src.OdprodajnaCena, IzvornaDatoteka = src.IzvornaDatoteka,
             ImportiranoUtc = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
  INSERT (ProductId, Vir, Sifra, Ean, NaSvetila, NaVidelektro, Kolicina, RednaCena, PopustOdstotek, OdprodajnaCena, IzvornaDatoteka)
  VALUES (src.ProductId, src.Vir, src.Sifra, src.Ean, src.NaSvetila, src.NaVidelektro, src.Kolicina, src.RednaCena,
          src.PopustOdstotek, src.OdprodajnaCena, src.IzvornaDatoteka);

DECLARE @Vstavljenih int = (SELECT COUNT(*) FROM pim.ClearanceItem);
DECLARE @VirovBrezUjemanja int = (SELECT COUNT(*) FROM #Odprodaja o
  WHERE NOT EXISTS (SELECT 1 FROM canon.Product p
                     WHERE UPPER(LTRIM(RTRIM(p.ItemID))) COLLATE SQL_Latin1_General_CP1_CI_AS
                         = UPPER(LTRIM(RTRIM(o.Sifra))) COLLATE SQL_Latin1_General_CP1_CI_AS));

SELECT Vrstic_v_pim_ClearanceItem = @Vstavljenih, Sifer_brez_ujemanja_v_canonProduct = @VirovBrezUjemanja;

DROP TABLE #Odprodaja;
